AVAILABLE_ICONS = list(CATEGORY_ICONS.keys())


@register.simple_tag
def category_icon(icon_name, css_class="h-4 w-4"):
    inner = CATEGORY_ICONS.get(icon_name) or CATEGORY_ICONS["more-horizontal"]
    return mark_safe(
        f'<svg class="{css_class}" fill="none" stroke="currentColor" viewBox="0 0 24 24">'
        f'{inner}</svg>'
    )
